"""Original Bjorni art, generated device rectangles: no filesystem at render time.

Game owns jump height, feeding, decay and saves. This plugin only selects a pose.
The eyes and sprites use the shared ground anchor, including skin scaling.
"""

try:
    from ubinascii import a2b_base64
except ImportError:
    from binascii import a2b_base64

_ACTIVE_INDEX = -1
_ACTIVE_RECTS = b''

# (first frame, number of frames, milliseconds per frame)
_LOOPS = {
    'idle': (0, 4, 300),
    'walk-right': (4, 4, 125),
    'walk-left': (8, 4, 125),
    'jump': (12, 5, 120),
    'greeting': (17, 4, 165),
    'sad': (21, 4, 275),
    'thinking': (25, 4, 220),
    'typing': (29, 4, 140),
    'happy': (33, 4, 180),
}
_STILLS = {'blink': 37, 'sleepy': 38, 'asleep': 39, 'hungry': 40,
           'eating': 41, 'sick': 42, 'surprised': 43}
_EYES = ((-17, -83), (17, -83))


def select_frame(eyes, mouth, sick=False, motion=None):
    action, tick = motion if motion else ('', 0)
    if mouth == 'dormindo' or eyes == 'dormindo':
        return _STILLS['asleep']
    if sick:
        return _STILLS['sick']
    if eyes in ('susto', 'assustado'):
        return _STILLS['surprised']
    if action == 'eating':
        # Chew between bites instead of holding an identical static pose.
        return _STILLS['eating'] if (tick // 180) % 2 == 0 else _LOOPS['happy'][0]
    if eyes == 'sono':
        return _STILLS['sleepy']
    if action in _STILLS:
        return _STILLS[action]
    if action in ('walk-left', 'walk-right', 'jump', 'greeting', 'typing', 'thinking'):
        state = action
    elif mouth == 'triste' or eyes in ('triste', 'chorando'):
        state = 'sad'
    elif eyes in ('feliz', 'alegre') or action == 'happy':
        state = 'happy'
    elif eyes == 'fechados':
        return _STILLS['blink']
    else:
        state = 'idle'
    start, length, delay = _LOOPS[state]
    if state == 'jump':
        return start + min(length - 1, max(0, tick) // delay)
    return start + (max(0, tick) // delay) % length


def render(E, R, P, A, eyes='normal', mouth='sorriso', sick=False, motion=None):
    global _ACTIVE_INDEX, _ACTIVE_RECTS
    idx = select_frame(eyes, mouth, sick, motion)
    if idx != _ACTIVE_INDEX:
        _ACTIVE_RECTS = a2b_base64(FRAMES[idx])
        _ACTIVE_INDEX = idx
    rectangles = _ACTIVE_RECTS
    for i in range(0, len(rectangles), 5):
        x, y, w, h, c = (rectangles[i], rectangles[i+1], rectangles[i+2],
                         rectangles[i+3], rectangles[i+4])
        R((x - 26) * 2.16, (y - 55) * 2.16, w * 2.16, h * 2.16, PALETTE[c])
    return _EYES


